import sys, json, urllib.request
URL='http://are-sidecar:8000/mcp'
SID='bd9a732f9077438ca6b20080b7313067'

def rpc(payload):
    data=json.dumps(payload).encode()
    req=urllib.request.Request(URL,data=data,method='POST',headers={
        'Content-Type':'application/json',
        'Accept':'application/json, text/event-stream',
        'mcp-session-id':SID,
    })
    with urllib.request.urlopen(req, timeout=30) as r:
        text=r.read().decode()
    out=[]
    for line in text.splitlines():
        if line.startswith('data: '):
            out.append(line[6:])
    if not out and text.strip():
        print(text)
        return None
    obj=json.loads('\n'.join(out))
    print(json.dumps(obj, indent=2, ensure_ascii=False))
    return obj

if __name__=='__main__':
    if sys.argv[1]=='list':
        rpc({'jsonrpc':'2.0','id':10,'method':'tools/list','params':{}})
    elif sys.argv[1]=='call':
        name=sys.argv[2]
        args=json.loads(sys.argv[3]) if len(sys.argv)>3 else {}
        rpc({'jsonrpc':'2.0','id':11,'method':'tools/call','params':{'name':name,'arguments':args}})
